#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# One-time setup for the fork's personal iOS app ("Paseo (devorbitus)", com.devorbitus.paseo):
# the Apple and Expo account values agents need to build it locally and ship it to TestFlight.
# Non-secret values go to ~/.paseo-fork/ios.env; secrets go to the macOS Keychain, where
# scripts/fork read them at build time. Safe to re-run: Enter keeps saved values.

TOTAL_STAGES=6
mkdir -p "$HOME/.paseo-fork"
ENV_FILE="$HOME/.paseo-fork/ios.env"
BUNDLE_ID="com.devorbitus.paseo"
KEYCHAIN_ASC_KEY="paseo-fork-asc-api-key"
KEYCHAIN_EXPO_TOKEN="paseo-fork-expo-token"
WRITTEN_KEYCHAIN=()

# keychain_store SERVICE VALUE saves VALUE as a generic password for this user (replacing any
# existing one), so no secret lands in a file.
keychain_store() {
  security add-generic-password -U -a "$USER" -s "$1" -w "$2" >/dev/null
  WRITTEN_KEYCHAIN+=("$1")
  printf '  %s✓ stored%s %s in your login Keychain\n' "$GREEN" "$RESET" "$1"
}

keychain_has() { security find-generic-password -a "$USER" -s "$1" >/dev/null 2>&1; }

banner "Personal Paseo iOS app: Apple + Expo setup"

stage "Apple Developer: team ID"
say "Your team ID tells EAS which Apple Developer team signs the app."
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Sign in, then find 'Membership details' and copy the Team ID (10 characters, e.g. AB12CD34EF)."
ask APPLE_TEAM_ID "Paste the Team ID:"
write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"
pause

stage "Apple Developer: register the app's bundle ID"
say "The personal app has its own bundle ID, $BUNDLE_ID, so it installs beside the App Store app."
open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
step "Choose 'App IDs' → Continue → type 'App' → Continue."
step "Description: Paseo devorbitus. Bundle ID: Explicit, $BUNDLE_ID"
step "Under Capabilities, tick 'Push Notifications'. Then Continue → Register."
note "If it says the ID is already registered, that's fine: open it and make sure Push Notifications is ticked."
pause "Press Enter once $BUNDLE_ID is registered with Push Notifications"

stage "App Store Connect: create the app record"
say "TestFlight needs an app record. It stays private; nothing is published to the App Store."
open_url "https://appstoreconnect.apple.com/apps"
step "Click '+' → New App. Platform: iOS."
step "Name: anything unique on the App Store, e.g. 'Paseo devorbitus'. Primary language: English (U.S.)."
step "Bundle ID: pick $BUNDLE_ID. SKU: paseo-devorbitus. User Access: Full Access. → Create."
step "On the new app page, open 'App Information' and copy the 'Apple ID' number (about 10 digits)."
ask ASC_APP_ID "Paste the app's Apple ID:"
write_env ASC_APP_ID "$ASC_APP_ID"
pause

stage "App Store Connect: API key for agents"
say "This key lets agents upload builds and manage signing without your Apple login."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Under 'Team Keys' (request access first if asked), click '+' / Generate API Key."
step "Name: Paseo fork agents. Access: App Manager. → Generate."
step "Copy the 'Issuer ID' shown above the keys table, and the new key's 'Key ID'."
ask ASC_ISSUER_ID "Paste the Issuer ID:"
ask ASC_KEY_ID "Paste the Key ID:"
write_env ASC_ISSUER_ID "$ASC_ISSUER_ID"
write_env ASC_KEY_ID "$ASC_KEY_ID"
step "Click 'Download' on that key. Apple lets you download the .p8 file only once."
default_p8="$HOME/Downloads/AuthKey_${ASC_KEY_ID}.p8"
if keychain_has "$KEYCHAIN_ASC_KEY" && ! confirm "A key is already in the Keychain. Replace it with $ASC_KEY_ID?"; then
  note "Keeping the stored key."
else
  ask ASC_P8_PATH "Path to the downloaded .p8 file [$default_p8]:"
  ASC_P8_PATH="${ASC_P8_PATH:-$default_p8}"
  while [[ ! -f "$ASC_P8_PATH" ]]; do
    warn "No file at $ASC_P8_PATH"
    ask ASC_P8_PATH "Path to the downloaded .p8 file:"
  done
  # Base64 keeps the multi-line PEM in a single Keychain value.
  keychain_store "$KEYCHAIN_ASC_KEY" "$(base64 < "$ASC_P8_PATH" | tr -d '\n')"
  if confirm "Delete the downloaded copy at $ASC_P8_PATH now that it's in the Keychain?"; then
    rm -f "$ASC_P8_PATH" && note "Deleted $ASC_P8_PATH."
  fi
fi
pause

stage "Expo: account and access token"
say "EAS (Expo's build tooling) signs and submits the app; the token lets agents use it unattended."
open_url "https://expo.dev/signup"
step "Sign up or log in. Your Expo username shows at the top left after login."
ask EXPO_OWNER "Your Expo username:"
write_env EXPO_OWNER "$EXPO_OWNER"
open_url "https://expo.dev/settings/access-tokens"
step "Click 'Create token'. Name: paseo-fork-agents. Copy the token (shown once)."
if keychain_has "$KEYCHAIN_EXPO_TOKEN" && ! confirm "A token is already in the Keychain. Replace it?"; then
  note "Keeping the stored token."
else
  ask_secret EXPO_TOKEN_VALUE "Paste the access token:"
  keychain_store "$KEYCHAIN_EXPO_TOKEN" "$EXPO_TOKEN_VALUE"
fi
pause

stage "TestFlight: testers and the iPhone app"
say "Internal testers get every build automatically, no App Review needed."
open_url "https://appstoreconnect.apple.com/apps/${ASC_APP_ID}/testflight/groups"
step "Under 'Internal Testing', click '+', name the group 'Me', and add yourself as a tester."
step "Enable 'Automatic Distribution' for the group if it's offered."
step "On your iPhone, install 'TestFlight' from the App Store and sign in with the same Apple ID."
note "The first build shows up in TestFlight after an agent uploads it; you'll get a TestFlight email."
pause "Press Enter when the group exists and TestFlight is on your phone"

finish
(( ${#WRITTEN_KEYCHAIN[@]} )) && note "stored in Keychain: ${WRITTEN_KEYCHAIN[*]}"
note "Tell your agent setup is done; it takes it from here."
printf '\n'
